<script lang="ts">
import {onMount} from 'svelte';import {api,type Shelf} from '../../lib/api';
type Bookcase={revision:number;id:number;name:string;room:string};type Action={kind:'shelves'|'bookcases';id:number;expected:string;revision:number;remove:boolean};
let shelves:Shelf[]=[];let cases:Bookcase[]=[];let bookcase='';let name='';let busy=false;let error='';let message='';let action:Action|null=null;let newName='';let token='';let prior='';let loading=true;let loaded=false;let loadError='';let loadSequence=0;
async function load(){const sequence=++loadSequence;loading=true;loadError='';try{const [nextShelves,nextCases]=await Promise.all([api<Shelf[]>('/api/shelves'),api<Bookcase[]>('/api/bookcases')]);if(sequence===loadSequence){shelves=nextShelves;cases=nextCases;loaded=true;}}catch(e){if(sequence===loadSequence)loadError=(e as Error).message;}finally{if(sequence===loadSequence)loading=false;}}
onMount(()=>{load();const refresh=()=>load();window.addEventListener('focus',refresh);return()=>window.removeEventListener('focus',refresh);});
async function add(e:SubmitEvent){e.preventDefault();busy=true;error='';try{await api<Shelf[]>('/api/shelves',{bookcase:bookcase.trim(),name:name.trim()});name='';await load();message='Shelf added.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
function start(kind:Action['kind'],id:number,expected:string,revision:number,remove=false){action={kind,id,expected,revision,remove};newName=expected;error='';}
async function save(){if(!action)return;busy=true;error='';const data={name:newName.trim(),expected_name:action.expected,expected_revision:action.revision};const payload=JSON.stringify([action,data]);if(payload!==prior){prior=payload;token=crypto.randomUUID();}try{await api(`/api/${action.kind}/${action.id}${action.remove?'/remove':''}`,{...data,request_key:token},action.remove?'POST':'PATCH');message=action.remove?'Location removed.':'Location renamed.';action=null;prior='';await load();window.dispatchEvent(new Event('library-inventory-changed'));}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="shelves_wrap"><form class="shelves_form" onsubmit={add}><label class="library-field">Bookcase<input required maxlength="200" bind:value={bookcase} placeholder="e.g. Living room / Left bookcase"/></label><label class="library-field">Shelf name<input required maxlength="200" bind:value={name} placeholder="e.g. Shelf 2"/></label><button class="library-button" disabled={busy}>{busy?'Saving…':'Add shelf'}</button></form>{#if error}<p role="alert" class="library-error">{error}</p>{/if}<p role="status">{message}</p>
{#if action}<form class="shelves_action" onsubmit={(e)=>{e.preventDefault();save();}}>{#if action.remove}<strong>Remove {action.expected}?</strong><p>{action.kind==='bookcases'?'This also removes its empty shelves. ':''}Removal is blocked if any current or archived copy still references this location. No books will be reassigned.</p>{:else}<label class="library-field">New {action.kind==='bookcases'?'bookcase':'shelf'} name<input bind:value={newName} maxlength="200" required disabled={busy}/></label>{/if}<div class="library-actions"><button class="library-button" disabled={busy}>{action.remove?'Confirm removal':'Save name'}</button><button type="button" class="library-button secondary" disabled={busy} onclick={()=>action=null}>Cancel</button></div></form>{/if}
{#if loadError}<div><p role="alert" class="library-error">Could not load locations: {loadError}</p><button class="library-button secondary" disabled={loading} onclick={load}>Retry loading locations</button></div>{/if}{#if loading&&!loaded}<p role="status">Loading locations…</p>{:else if loaded&&!cases.length}<p>No shelves yet. Add one above, or leave your books unassigned for now.</p>{:else if loaded}{#each cases as bc}<section class="shelf_case"><div class="shelf_case_heading"><h2>{bc.name}</h2><div class="library-actions"><button class="library-button secondary" disabled={busy} onclick={()=>start('bookcases',bc.id,bc.name,bc.revision)}>Rename bookcase</button><button class="library-button secondary" disabled={busy} onclick={()=>start('bookcases',bc.id,bc.name,bc.revision,true)}>Remove bookcase</button></div></div><ul class="shelves_list">{#each shelves.filter(s=>s.bookcase_id===bc.id) as s}<li><strong>{s.name}</strong><div class="library-actions"><button class="library-button secondary" disabled={busy} onclick={()=>start('shelves',s.id,s.name,s.revision)}>Rename shelf</button><button class="library-button secondary" disabled={busy} onclick={()=>start('shelves',s.id,s.name,s.revision,true)}>Remove shelf</button></div></li>{/each}</ul>{#if !shelves.some(s=>s.bookcase_id===bc.id)}<p>This bookcase has no shelves.</p>{/if}</section>{/each}{/if}<p class="library-help">Renaming keeps all book locations and loan history. Move current copies to another shelf before removing an occupied location; locations referenced by archived copies are retained.</p></div>
<style>@layer components {.shelves_wrap{display:grid;gap:var(--space-4)}.shelves_form{display:grid;grid-template-columns:2fr 1fr auto;align-items:end;gap:var(--space-3);@media(width<48rem){grid-template-columns:1fr}}.shelves_list{display:grid;gap:var(--space-3);li{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:var(--space-3);border-bottom:var(--border-width) solid var(--border);padding:var(--space-3)}}.shelf_case,.shelves_action{display:grid;gap:var(--space-3);border:var(--border-width) solid var(--border);padding:var(--space-4);border-radius:var(--radius-main);background:var(--background-3)}.shelf_case_heading{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:var(--space-3);h2{font-size:var(--h5)}}}</style>
